import{_ as t,o as r,c as p,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-09-27","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-09-27","date":"2022-09-27T00:00:00.000Z","updated":"2022-09-30T00:00:00.000Z","tags":["Ceph","Orchestrator","Storage Cluster","Upgrade","Error Handling"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-09-27.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-09-27.md","lastUpdated":1780460162000}'),a={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-09-27.md"};function i(o,e,l,n,_,d){return r(),p("div",null,[...e[0]||(e[0]=[s("<p>本次Ceph Orchestrator会议重点讨论了以下议题：</p><ol><li><p><strong>处理离线主机的问题</strong>：会议介绍了在集群升级过程中遇到离线主机时的处理方法。目前，如果主机离线，升级会失败，并抛出不可预期的异常。讨论了如何改进这一错误处理，例如通过标记离线主机并继续升级其他节点，或者在升级前进行快速检查。</p></li><li><p><strong>RW spec格式</strong>：讨论了在多站点部署中使用的RW spec格式，以及是否应该将其用于新的多站点部署模型。决定保留相同的spec格式，并提供文档说明以减少潜在的混淆。</p></li><li><p><strong>版本信息</strong>：讨论了是否应该在Café ADM中嵌入版本信息。决定在完成所有测试后，在拆分之前处理这个问题。</p></li><li><p><strong>Cephadm的部署</strong>：讨论了如何获取编译后的Cephadm版本，以及如何处理签名问题。决定通过电子邮件向社区寻求帮助。</p></li><li><p><strong>Cephadm的获取方式</strong>：讨论了如何获取编译后的Cephadm二进制文件。目前，已经有一些daily build和RPM包可用。</p></li></ol><p>会议决定采取以下行动：</p><ul><li>改进离线主机处理的错误处理机制。</li><li>保留RW spec格式，并增加文档说明。</li><li>在测试完成后，在拆分之前嵌入Café ADM的版本信息。</li><li>通过电子邮件向社区寻求获取编译后的Cephadm二进制文件的帮助。</li><li>确认daily build和RPM包的可用性，并解决签名问题。</li></ul>",4)])])}const g=t(a,[["render",i]]);export{h as __pageData,g as default};
